.plotcn-chart, .plotcn-chart-scope, [data-chart].plotcn-chart {
  container-type: size !important;
  --chart-background: var(--background, oklch(0.145 0 0));
  --chart-foreground: var(--foreground, oklch(0.985 0 0));
  --chart-muted-foreground: var(--muted-foreground, oklch(0.708 0 0));
  --chart-border: var(--border, oklch(0.269 0 0));
  --chart-grid: var(--border, oklch(0.269 0 0));
  --chart-grid-emphasis: var(--muted-foreground, oklch(0.556 0 0));
  --chart-axis: var(--muted-foreground, oklch(0.708 0 0));
  --chart-axis-emphasis: var(--foreground, oklch(0.985 0 0));
  --chart-axis-label: var(--chart-axis);
  --chart-axis-line: var(--chart-border);
  --chart-zero-line: var(--muted-foreground, oklch(0.556 0 0));
  --chart-crosshair: var(--muted-foreground, oklch(0.708 0 0));
  --chart-focus: var(--foreground, oklch(0.985 0 0));
  --chart-selection: var(--foreground, oklch(0.985 0 0));
  --chart-positive: var(--foreground, oklch(0.985 0 0));
  --chart-negative: var(--muted-foreground, oklch(0.708 0 0));
  --chart-warning: var(--muted-foreground, oklch(0.708 0 0));
  --chart-1: var(--color-chart-1, #f4f4f5);
  --chart-2: var(--color-chart-2, #d4d4d8);
  --chart-3: var(--color-chart-3, #a1a1aa);
  --chart-4: var(--color-chart-4, #71717a);
  --chart-5: var(--color-chart-5, #52525b);
  --chart-6: var(--color-chart-6, #3f3f46);
  --chart-7: var(--color-chart-7, #e4e4e7);
  --chart-8: var(--color-chart-8, #27272a);
  --chart-tooltip-background: var(--chart-tooltip-background, var(--card, var(--background, oklch(0.145 0 0))));
  --chart-tooltip-foreground: var(--chart-tooltip-foreground, var(--card-foreground, var(--foreground, oklch(0.985 0 0))));
  --chart-tooltip-muted: var(--chart-tooltip-muted, var(--muted-foreground, oklch(0.708 0 0)));
  --chart-tooltip-border: var(--chart-tooltip-border, var(--border, oklch(0.269 0 0)));
  color: var(--chart-foreground); background: var(--chart-background); font-family: inherit; font-variant-numeric: tabular-nums;
}
[data-chart-palette="mono"] { --chart-1: var(--foreground); --chart-2: oklch(.65 0 0); --chart-3: oklch(.55 0 0); --chart-4: oklch(.45 0 0); --chart-5: oklch(.75 0 0); --chart-6: oklch(.35 0 0); --chart-7: oklch(.85 0 0); --chart-8: oklch(.6 0 0); }
[data-chart-palette="colorblind"] { --chart-1: oklch(.57 .13 240); --chart-2: oklch(.7 .16 65); --chart-3: oklch(.62 .13 165); --chart-4: oklch(.65 .13 340); --chart-5: oklch(.75 .1 220); --chart-6: oklch(.6 .16 45); --chart-7: oklch(.8 .13 95); --chart-8: var(--foreground); }
.plotcn-chart :focus-visible { outline: 2px solid var(--chart-focus); outline-offset: 3px; }

/* Tooltip container constraints and auto-adjusting responsive behavior */
.plotcn-chart .recharts-tooltip-wrapper {
  max-width: calc(100cqw - 16px) !important;
  max-height: calc(100cqh - 16px) !important;
  pointer-events: none !important;
  z-index: 50 !important;
}

.plotcn-chart .recharts-tooltip-wrapper > * {
  max-width: calc(100cqw - 16px) !important;
  max-height: calc(100cqh - 16px) !important;
  box-sizing: border-box !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: thin !important;
}

.plotcn-chart-tooltip,
.plotcn-chart [role="tooltip"],
.plotcn-chart .recharts-default-tooltip {
  border: 1px solid var(--chart-tooltip-border);
  background: var(--chart-tooltip-background);
  color: var(--chart-tooltip-foreground);
  border-radius: 8px;
  padding: 8px 12px;
  font: 12px/1.5 inherit;
  font-variant-numeric: tabular-nums;
  min-width: min(140px, calc(100cqw - 16px));
  max-width: min(320px, calc(100cqw - 16px));
  max-height: calc(100cqh - 16px);
  box-sizing: border-box;
  overflow-y: auto;
  scrollbar-width: thin;
  pointer-events: none;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
  backdrop-filter: blur(8px);
  transition: all 0.15s ease-out;
}

:is(.charts-surface[data-theme="light"], html:not(.dark) .charts-surface[data-theme="follow"], html:not(.dark)) .plotcn-chart-tooltip,
:is(.charts-surface[data-theme="light"], html:not(.dark) .charts-surface[data-theme="follow"], html:not(.dark)) [role="tooltip"].plotcn-chart-tooltip,
:is(.charts-surface[data-theme="light"], html:not(.dark) .charts-surface[data-theme="follow"], html:not(.dark)) .recharts-default-tooltip {
  border-color: var(--chart-tooltip-border, #e4e4e7);
  background: var(--chart-tooltip-background, #ffffff);
  color: var(--chart-tooltip-foreground, #09090b);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.04);
}

.plotcn-chart-tooltip-compact {
  min-width: min(80px, calc(100cqw - 12px)) !important;
  max-width: calc(100cqw - 12px) !important;
  max-height: calc(100cqh - 12px) !important;
  padding: 4px 8px !important;
  font-size: 10px !important;
  line-height: 1.35 !important;
  border-radius: 6px !important;
}

.plotcn-tooltip-label { color: var(--chart-tooltip-muted); font-size: 11px; }
.plotcn-tooltip-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.plotcn-tooltip-value { font-weight: 600; font-variant-numeric: tabular-nums; }

/* Responsive adjustments based on chart container width */
@container (max-width: 440px) {
  .plotcn-chart-tooltip,
  .plotcn-chart [role="tooltip"],
  .plotcn-chart .recharts-tooltip-wrapper > div {
    min-width: min(110px, calc(100cqw - 12px)) !important;
    max-width: calc(100cqw - 12px) !important;
    padding: 6px 9px !important;
    font-size: 11px !important;
    line-height: 1.35 !important;
    border-radius: 6px !important;
  }
  .plotcn-tooltip-row { gap: 10px !important; }
  .plotcn-chart .recharts-tooltip-wrapper .text-sm { font-size: 11.5px !important; }
}

@container (max-width: 320px) {
  .plotcn-chart-tooltip,
  .plotcn-chart [role="tooltip"],
  .plotcn-chart .recharts-tooltip-wrapper > div {
    min-width: 0 !important;
    max-width: calc(100cqw - 8px) !important;
    padding: 4px 6px !important;
    font-size: 10px !important;
    line-height: 1.25 !important;
    border-radius: 5px !important;
  }
  .plotcn-tooltip-row { gap: 6px !important; }
  .plotcn-chart .recharts-tooltip-wrapper .text-sm { font-size: 10.5px !important; }
}

/* Responsive adjustments based on chart container height */
@container (max-height: 280px) {
  .plotcn-chart-tooltip,
  .plotcn-chart [role="tooltip"],
  .plotcn-chart .recharts-tooltip-wrapper > div {
    max-height: calc(100cqh - 10px) !important;
    padding: 5px 8px !important;
    font-size: 10.5px !important;
    line-height: 1.3 !important;
  }
  .plotcn-chart .recharts-tooltip-wrapper [class*="pb-"] { padding-bottom: 3px !important; }
  .plotcn-chart .recharts-tooltip-wrapper [class*="mb-"] { margin-bottom: 3px !important; }
  .plotcn-chart .recharts-tooltip-wrapper [class*="space-y-"] { gap: 2px !important; }
}

@container (max-height: 200px) {
  .plotcn-chart-tooltip,
  .plotcn-chart [role="tooltip"],
  .plotcn-chart .recharts-tooltip-wrapper > div {
    max-height: calc(100cqh - 6px) !important;
    padding: 3px 6px !important;
    font-size: 9.5px !important;
    line-height: 1.2 !important;
  }
  .plotcn-chart .recharts-tooltip-wrapper [class*="pb-"] { padding-bottom: 1.5px !important; }
  .plotcn-chart .recharts-tooltip-wrapper [class*="mb-"] { margin-bottom: 1.5px !important; }
}
